def gaps(prefix, n0, n1, opts, ans, notes):
    return [dict({"prompt": f"Κενό [{i}]", "options": opts, "answer": ans[i]}, **({"answer_note": notes[i]} if i in notes else {})) for i in range(n0, n1 + 1)]

